#
# fw_update build script (library extraScript of the fw_update usermod)
#
# 1. Sets FW_UPDATE_BUILD_ID (YYMMDDHHMMSS, local build time) for the usermod's own sources only,
#    so each build gets a new ID without recompiling the rest of WLED.
# 2. After firmware.bin is built, optionally publishes it to a local clone of the firmware repo:
#      <clone>/<WLED_RELEASE_NAME>/<build id>.bin   (newest 10 per device are kept)
#    committed on branch "staging" and pushed; a PR staging -> main is opened if none is open.
#    Enable by setting the clone path in the environment variable WLED_FW_REPO
#    or in platformio_override.ini:  custom_fw_update_repo = C:/path/to/wled-firmware
#    Publishing problems are printed as warnings and never fail the build.

Import("env")

import json
import os
import re
import shutil
import subprocess
import urllib.error
import urllib.request
from datetime import datetime
from urllib.parse import urlparse

from SCons.Script import DefaultEnvironment

KEEP_BUILDS = 10
STAGING = "staging"
MAIN = "main"

projenv = DefaultEnvironment()

# one ID per build, even if this script is loaded more than once
BUILD_ID = projenv.get("FW_UPDATE_BUILD_ID") or datetime.now().strftime("%y%m%d%H%M%S")
projenv["FW_UPDATE_BUILD_ID"] = BUILD_ID

# usermod sources only (this env belongs to the fw_update library)
env.Append(CPPDEFINES=[("FW_UPDATE_BUILD_ID", f'\\"{BUILD_ID}\\"')])


def _warn(msg):
    print(f"\033[93mfw_update: {msg}\033[0m")


def _release_name(e):
    for item in e.get("CPPDEFINES", []):
        if isinstance(item, (tuple, list)) and item[0] == "WLED_RELEASE_NAME":
            return str(item[1]).replace('\\"', "").replace('"', "")
    return None


def _git(repo, *args, inp=None):
    r = subprocess.run(["git", "-C", repo, *args], input=inp, capture_output=True, text=True,
                       env={**os.environ, "GIT_TERMINAL_PROMPT": "0"})
    if r.returncode != 0:
        raise RuntimeError(f"git {' '.join(args)}: {r.stderr.strip() or r.stdout.strip()}")
    return r.stdout.strip()


def _api(base, token, method, path, body=None):
    req = urllib.request.Request(f"{base}/api/v1{path}", method=method,
                                 data=json.dumps(body).encode() if body is not None else None)
    req.add_header("Authorization", f"token {token}")
    req.add_header("Content-Type", "application/json")
    with urllib.request.urlopen(req, timeout=15) as resp:
        return json.loads(resp.read() or b"null")


def _publish(repo_dir, release, bin_path):
    remote = _git(repo_dir, "remote", "get-url", "origin")
    u = urlparse(remote)
    if u.scheme not in ("http", "https"):
        raise RuntimeError(f"origin must be an http(s) URL, got {remote}")
    owner_repo = u.path.strip("/")
    owner_repo = owner_repo[:-4] if owner_repo.endswith(".git") else owner_repo
    base = f"{u.scheme}://{u.hostname}" + (f":{u.port}" if u.port else "")

    cred = _git(repo_dir, "credential", "fill", inp=f"url={base}/{owner_repo}\n\n")
    token = next((l[9:] for l in cred.splitlines() if l.startswith("password=")), "")
    if not token:
        raise RuntimeError("no credential for the firmware repo (git credential fill)")

    if _git(repo_dir, "status", "--porcelain"):
        raise RuntimeError(f"{repo_dir} has uncommitted changes")

    _git(repo_dir, "fetch", "origin", "--prune")
    pulls = _api(base, token, "GET", f"/repos/{owner_repo}/pulls?state=open&limit=50") or []
    open_pr = next((p for p in pulls if p["head"]["ref"] == STAGING and p["base"]["ref"] == MAIN), None)
    has_remote_staging = bool(_git(repo_dir, "branch", "-r", "--list", f"origin/{STAGING}"))

    if open_pr and has_remote_staging:
        _git(repo_dir, "checkout", "-B", STAGING, f"origin/{STAGING}")
        reset = False
    else:
        # previous PR merged or closed: start a fresh staging branch from main
        _git(repo_dir, "checkout", "-B", STAGING, f"origin/{MAIN}")
        reset = True

    folder = os.path.join(repo_dir, release)
    os.makedirs(folder, exist_ok=True)
    shutil.copyfile(bin_path, os.path.join(folder, f"{BUILD_ID}.bin"))
    builds = sorted(f for f in os.listdir(folder) if re.fullmatch(r"\d{12}\.bin", f))
    for old in builds[:-KEEP_BUILDS]:
        _git(repo_dir, "rm", "-q", "--", f"{release}/{old}")
    _git(repo_dir, "add", "--", release)
    _git(repo_dir, "commit", "-q", "-m", f"{release} {BUILD_ID}")
    if reset:
        _git(repo_dir, "push", "-q", "--force", "origin", STAGING)
    else:
        _git(repo_dir, "push", "-q", "origin", STAGING)

    if not open_pr:
        open_pr = _api(base, token, "POST", f"/repos/{owner_repo}/pulls", {
            "head": STAGING, "base": MAIN,
            "title": f"Firmware builds {datetime.now():%Y-%m-%d}",
            "body": "Builds added by fw_update_build.py. Merge to make them available to the devices.",
        })
    print(f"fw_update: {release}/{BUILD_ID}.bin published, PR {open_pr['html_url']}")


def _after_bin(source, target, env):
    print(f"fw_update: build ID {BUILD_ID}")
    repo_dir = os.environ.get("WLED_FW_REPO") or env.GetProjectOption("custom_fw_update_repo", "")
    if not repo_dir:
        return
    release = _release_name(env)
    if not release or not re.fullmatch(r"[A-Za-z0-9._-]+", release):
        _warn(f"not published: WLED_RELEASE_NAME missing or has unsupported characters ({release})")
        return
    try:
        _publish(os.path.abspath(os.path.expanduser(repo_dir)), release, str(target[0]))
    except (RuntimeError, OSError, urllib.error.URLError, KeyError, ValueError) as e:
        _warn(f"not published: {e}")


# the library script may be loaded more than once per environment
if not projenv.get("FW_UPDATE_HOOKED"):
    projenv["FW_UPDATE_HOOKED"] = True
    projenv.AddPostAction("$BUILD_DIR/${PROGNAME}.bin", _after_bin)
# AI: end
